package nx.updater;
import java.net.*;import java.nio.file.*;import java.io.*;import java.security.*;import java.util.*;import java.util.function.*;
public final class DownloadManager {
 public interface Progress{void update(long done,long total,long bytesPerSecond,String status);}
 private final boolean localTest;
 public DownloadManager(boolean localTest){this.localTest=localTest;}
 public void validate(String text)throws Exception{URI u=new URI(text);String h=u.getHost();boolean local=localTest&&"http".equals(u.getScheme())&&("127.0.0.1".equals(h)||"localhost".equals(h));if(u.getUserInfo()!=null||u.getFragment()!=null||(!local&&!("https".equals(u.getScheme())&&Arrays.asList("github.com","api.github.com","release-assets.githubusercontent.com","objects.githubusercontent.com").contains(h))))throw new SecurityException("Servidor de descarga no permitido");}
 public HttpURLConnection connect(String url,Map<String,String> headers)throws Exception{for(int hops=0;hops<6;hops++){validate(url);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(4000);c.setReadTimeout(8000);c.setRequestProperty("User-Agent","NX-Updater/0.1.0");for(Map.Entry<String,String> h:headers.entrySet())c.setRequestProperty(h.getKey(),h.getValue());int s=c.getResponseCode();if(s==301||s==302||s==303||s==307||s==308){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException("Redirección sin destino");url=new URL(new URL(url),next).toString();continue;}return c;}throw new IOException("Demasiadas redirecciones");}
 public byte[] bytes(String url,int max)throws Exception{HttpURLConnection c=connect(url,Collections.emptyMap());try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>=0){if(b.size()+n>max)throw new IOException("Respuesta demasiado grande");b.write(buf,0,n);}return b.toByteArray();}}finally{c.disconnect();}}
 public Path download(UpdateManifest.Entry e,Path dir,BooleanSupplier cancel,Progress progress)throws Exception{for(Path x=dir.toAbsolutePath();x!=null;x=x.getParent())if(Files.isSymbolicLink(x))throw new SecurityException("Carpeta simbólica");Files.createDirectories(dir);Path part=dir.resolve(e.sha256+".part"),done=dir.resolve(e.sha256+".bin");if(Files.isSymbolicLink(part)||Files.isSymbolicLink(done))throw new SecurityException("Archivo simbólico");if(Files.exists(done)&&Files.size(done)==e.size&&sha(done).equals(e.sha256))return done;Files.deleteIfExists(done);long offset=Files.exists(part)?Files.size(part):0;if(offset>e.size){Files.delete(part);offset=0;}if(offset==e.size){if(sha(part).equals(e.sha256)){Files.move(part,done,StandardCopyOption.REPLACE_EXISTING);return done;}Files.delete(part);offset=0;}
  Map<String,String> headers=new HashMap<>();if(offset>0)headers.put("Range","bytes="+offset+"-");HttpURLConnection c=connect(e.url,headers);long started=System.nanoTime(),initial=offset;
  try{int status=c.getResponseCode();if(status==206){String range=c.getHeaderField("Content-Range");if(!("bytes "+offset+"-").equals(range==null?null:range.substring(0,Math.min(range.length(),("bytes "+offset+"-").length()))))throw new IOException("Rango inválido");if(!range.endsWith("/"+e.size))throw new IOException("Tamaño del rango inválido");}else if(status==200){offset=0;initial=0;}else throw new IOException("Descarga HTTP "+status);
   try(InputStream in=c.getInputStream();OutputStream out=Files.newOutputStream(part,StandardOpenOption.CREATE,offset>0?StandardOpenOption.APPEND:StandardOpenOption.TRUNCATE_EXISTING)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))>=0){if(cancel.getAsBoolean())throw new InterruptedIOException("Descarga cancelada; se conserva el parcial");if(offset+n>e.size)throw new IOException("Descarga excede manifiesto");out.write(buf,0,n);offset+=n;long secs=Math.max(1,System.nanoTime()-started);progress.update(offset,e.size,(offset-initial)*1000000000L/secs,"DESCARGANDO");}}
   if(offset!=e.size)throw new EOFException("Descarga incompleta; puede reanudarse");progress.update(offset,e.size,0,"VERIFICANDO SHA-256");if(!sha(part).equals(e.sha256)){Files.delete(part);throw new SecurityException("Archivo corrupto: SHA256 no coincide");}Files.move(part,done,StandardCopyOption.REPLACE_EXISTING);return done;
  }finally{c.disconnect();}}
 public static String sha(Path p)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(p)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format("%02x",b&255));return s.toString();}
}
